import{_ as r,l,o as e,c as s,v as t,p as n,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"紧凑胶模型校准","description":"","frontmatter":{"title":"紧凑胶模型校准","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-model-calibration.md","filePath":"litho/resist-model-calibration.md","lastUpdated":1789023840000}'),c={name:"litho/resist-model-calibration.md"};function E(m,a,_,A,u,D){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="紧凑胶模型校准" tabindex="-1">紧凑胶模型校准 <a class="header-anchor" href="#紧凑胶模型校准" aria-label="Permalink to &quot;紧凑胶模型校准&quot;">​</a></h1><div class="epigraph"><p>CM 族把空中像收成边；校准是把 FEM 与 gauge 上的残差压进可外推的几项，而不是把实验室 Mack 方程塞进全芯片。</p><footer>—— 对照 Mack 紧凑抗蚀剂模型与 EDA CM1 族校准通称</footer></div><p><a href="/litho/domain-decomposition-mask">上一课</a>让严格近场可以按窗存在。缺口是 OPC 迭代仍要毫秒级前向：<a href="/litho/resist-compact-model">胶紧凑模型</a> 必须在本层胶、本 PEB、本显影上标定。本课钉校准。用哪些图形当样本，留给[下一课](/litho/test-patterns-gauges）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>紧凑模型有模糊核、阈值（常变阈值）、加载项。参数若不在本工艺的测量上拟合，SRAM 拐角会系统性偏，优化把误差修进掩模。校准的问题是：选代价函数（CD、EPE、通过焦点）、选正则（防项数爆炸）、选保持集（防只拟合标定线）。严格 EMF 教师改善的是光学输入；胶参数仍要晶圆或显影实验。</p><p>缺口是<strong>拟合协议</strong>，不是再推导酸扩散。把「模型版本号」当物理常数，换胶批次会在不知情时把全库 OPC 作废。</p><h3 id="光学、胶、刻蚀必须分校准" tabindex="-1">光学、胶、刻蚀必须分校准 <a class="header-anchor" href="#光学、胶、刻蚀必须分校准" aria-label="Permalink to &quot;光学、胶、刻蚀必须分校准&quot;">​</a></h3><p>把刻蚀负载塞进胶阈值，短期残差好看，换腔体时胶模型一起坏。<a href="/litho/etch-in-opc">刻蚀进 OPC</a> 已警告。本课只标定 ADI。AEI 留给后课刻蚀校准。</p><p><span class="marginnote">EUV 紧凑模型标定的是均值轮廓。泊松缺孔不在最小二乘 CD 里，见随机课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据：FEM 晶圆、CD-SEM、有时 OCD；覆盖通过节距、孤立/密集、二维。优化：非线性最小二乘或正则化反演。验收：保持集残差、热点 clips、跨剂量焦点。版本绑定：胶批次、扫描机照明文件、掩模 3D 核版本。</p><p>与严格电磁：先锁光学（含 mask 3D），再锁胶，避免两项互吞。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>变阈值把「同一强度不同环境印出不同 CD」收成几个图像特征（斜率、密度）。特征若与真实失效模式不正交，会出现补偿：光学错用胶来背。残差空间相关（下一课分析）是诊断：通过节距的系统正弦往往是光学核，而不是少一个胶项。</p>',14)),(e(),n(p,null,{default:i(()=>[h(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E5%85%89%E5%AD%A6%20%2B%20mask%203D%22%5D%20--%3E%20CM%5B%22%E7%B4%A7%E5%87%91%E8%83%B6%3A%20%E6%A8%A1%E7%B3%8A%20%2B%20%E9%98%88%E5%80%BC%22%5D%0A%20%20GAUGE%5B%22FEM%20%2F%20CD%22%5D%20--%3E%20FIT%5B%22%E6%8B%9F%E5%90%88%E5%8F%82%E6%95%B0%22%5D%0A%20%20FIT%20--%3E%20CM%0A%20%20CM%20--%3E%20HOLD%5B%22%E4%BF%9D%E6%8C%81%E9%9B%86%E6%AE%8B%E5%B7%AE%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>校准不创造光子，不保证未抽样图形。过拟合的 20 项模型在 TAPOUT 后热区爆炸，比 5 项略差但稳定的模型更危险。不写某 EDA 的秘密项公式。</p><p>后课默认：ADI 模型有版本与保持集；下一课把 gauge 设计本身当成会污染拟合的实验设计问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>紧凑胶校准绑定胶、PEB、显影与光学核版本。</li><li>光学/胶/刻蚀分拟合；EUV 均值模型不含随机尾。</li><li>保持集与热点 clips 比标定线 RMSE 更重要。</li><li>出处：Mack 紧凑抗蚀剂论述；CM1 族产线校准通称。</li></ul>',5))])}const B=r(c,[["render",E]]);export{f as __pageData,B as default};
